var DIGITS = "零壹贰叁肆伍陆柒捌玖";
function groupToCN(g){
  var units = ["", "拾", "佰", "仟"];
  var s = ""; var zero = false; var started = false;
  var len = g.length;
  for (var i = 0; i < len; i++){
    var d = g.charAt(i) - "0";
    var u = len - 1 - i;
    if (d === 0){ if (started) zero = true; }
    else { if (zero){ s += "零"; zero = false; } s += DIGITS[d] + units[u]; started = true; }
  }
  return s;
}
function intPartToCN(s){
  if (s === "0") return "零";
  var groups = []; var t = s;
  while (t.length > 0){ groups.unshift(t.slice(-4)); t = t.slice(0, -4); }
  var big = ["兆", "亿", "万", ""];
  var result = "";
  for (var i = 0; i < groups.length; i++){
    var g = groups[i];
    var bu = big[big.length - groups.length + i];
    var sec = groupToCN(g);
    if (sec === ""){
      if (result !== "" && !result.endsWith("零")) result += "零";
      continue;
    }
    result += sec + bu;
  }
  if (result.endsWith("零")) result = result.slice(0, -1);
  return result === "" ? "零" : result;
}
function rmbUpper(amount){
  if (isNaN(amount)) return null;
  var neg = amount < 0;
  amount = Math.abs(amount);
  if (amount >= 1e16) return "数值过大，仅支持到万亿级";
  var s = amount.toFixed(2);
  var parts = s.split(".");
  var intStr = parts[0].replace(/^0+/, "") || "0";
  var decStr = parts[1];
  var jiao = decStr.charAt(0) - "0";
  var fen = decStr.charAt(1) - "0";
  if (intStr === "0"){
    var d2 = "";
    if (jiao > 0) d2 += DIGITS[jiao] + "角";
    if (jiao === 0 && fen > 0) d2 += "零";
    if (fen > 0) d2 += DIGITS[fen] + "分";
    if (d2 === "") d2 = "零元整";
    else d2 = "零元" + d2;
    return (neg ? "负" : "") + d2;
  }
  var res = intPartToCN(intStr);
  if (jiao === 0 && fen === 0) res += "元整";
  else {
    res += "元";
    if (jiao > 0) res += DIGITS[jiao] + "角";
    if (jiao === 0 && fen > 0) res += "零";
    if (fen > 0) res += DIGITS[fen] + "分";
  }
  return (neg ? "负" : "") + res;
}
function rmbDigits(amount){
  if (isNaN(amount)) return null;
  var neg = amount < 0; amount = Math.abs(amount);
  var s = amount.toFixed(2);
  var p = s.split(".");
  var intStr = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return (neg ? "-" : "") + intStr + "." + p[1];
}
var EXPORTS = { rmbUpper: rmbUpper, rmbDigits: rmbDigits };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RmbForgePure = EXPORTS; }
